var files, files2, olo, olo_e, ololol, ololol2, ololol3, names;
olo=""
olo_e=""
ololol=""
ololol3=""
names=""

if progress=2
{

files=file_bin_open(global.load, 0)

while(real(rmax)>0)
{
goto=""; olo=""; olo_e=""; ololol2=0; names=""
sk_load_data("goto", susk+24, files, 4); goto=string(real(goto)+32)
olo_e=sk_spr_name2()
olo=sk_spr_name()

ololol=variable_local_get(olo_e)
while(string_length(ololol)!=3){ololol="0"+ololol}

while(1){if file_exists(global.save+"\spr\"+olo+string(ololol2)+ololol+".spz"){ololol2+=1}else{break}}

for(i=0; i!=-1; i+=1)
{
ololol3=string(i)
while(string_length(ololol3)!=3){ololol3="0"+ololol3}
if !file_exists(global.save+"\spr\"+olo+string(ololol2)+ololol3+".spz"){names=olo+string(ololol2)+ololol3; break}
}

files2=file_bin_open(global.save+"\spr\"+names+".spz", 0)
file_bin_seek(files, susk)
repeat(real(goto)){file_bin_write_byte(files2, file_bin_read_byte(files))}
file_bin_close(files2)

susk+=real(goto)
}

file_bin_close(files)

}

